"use client";

import * as React from "react";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { HeartIcon } from "lucide-react";

import { cn } from "@/lib/utils";

import "./like-burst.css";

/** Keep in sync with the nth-child choreography in like-burst.css. */
const LIKE_BURST_PARTICLE_COUNT = 7;

/**
 * The ring and every particle group run for the full burst duration, so the
 * burst is done once all of them report in. The per-dot animations on their
 * pseudo-elements share that clock and are not counted.
 */
const LIKE_BURST_SETTLE_ANIMATIONS = new Set([
  "like-burst-ring",
  "like-burst-particle",
]);
const LIKE_BURST_SETTLE_COUNT = 1 + LIKE_BURST_PARTICLE_COUNT;

type ButtonProps = React.ComponentProps<typeof ButtonPrimitive>;
type LikeBurstClickEvent = Parameters<NonNullable<ButtonProps["onClick"]>>[0];

export type LikeBurstProps = Omit<
  ButtonProps,
  "aria-pressed" | "children" | "duration" | "onClick" | "size"
> & {
  /** Controlled liked state. */
  liked?: boolean;
  /** Initial liked state for uncontrolled usage. */
  defaultLiked?: boolean;
  /** Called when the control requests a liked-state change. */
  onLikedChange?: (liked: boolean) => void;
  /** Called before the liked state changes. Prevent default to cancel the change. */
  onClick?: (event: LikeBurstClickEvent) => void;
  /** Accessible action label while unliked. Applied only when icon-only. */
  likeLabel?: string;
  /** Accessible action label while liked. Applied only when icon-only. */
  unlikeLabel?: string;
  /** Optional content placed after the heart. */
  children?: React.ReactNode;
  /**
   * Heart size. Numbers are interpreted as pixels; CSS lengths are also
   * accepted. Defaults to 32px via the `--like-burst-size` custom property,
   * which can also be set in CSS. The ring and particles scale with it.
   */
  iconSize?: number | string;
  /**
   * Total burst duration in milliseconds; every phase keeps its share of it.
   * Defaults to 700ms via the `--like-burst-duration` custom property, which
   * can also be set in CSS.
   */
  duration?: number;
  /** Classes applied to the heart and burst wrapper. */
  iconClassName?: string;
};

type LikeBurstStyle = React.CSSProperties & {
  "--like-burst-duration"?: string;
  "--like-burst-size"?: string;
};

export function LikeBurst({
  liked,
  defaultLiked = false,
  onLikedChange,
  onClick,
  likeLabel = "Like",
  unlikeLabel = "Unlike",
  children,
  iconSize,
  duration,
  className,
  iconClassName,
  disabled,
  ref,
  style,
  ...props
}: LikeBurstProps) {
  const [internalLiked, setInternalLiked] = React.useState(defaultLiked);
  const controlled = liked !== undefined;
  const isLiked = controlled ? liked : internalLiked;
  const previousLikedRef = React.useRef(isLiked);
  const likeIntentRef = React.useRef(false);
  const [burstId, setBurstId] = React.useState(0);
  const [burstActive, setBurstActive] = React.useState(false);
  const settledAnimationsRef = React.useRef(0);
  const likeBurstStyle: LikeBurstStyle = { ...style };

  if (duration !== undefined) {
    likeBurstStyle["--like-burst-duration"] = `${duration}ms`;
  }

  if (iconSize !== undefined) {
    likeBurstStyle["--like-burst-size"] =
      typeof iconSize === "number" ? `${iconSize}px` : iconSize;
  }

  // A burst only belongs to a liked heart, so unliking mid-burst drops it.
  if (burstActive && !isLiked) {
    setBurstActive(false);
  }

  // The burst celebrates user intent: it plays when `isLiked` turns true after
  // a click asked for it — immediately for optimistic parents, or once a
  // non-optimistic parent commits the result — but never for controlled state
  // arriving from a fetch or a realtime update.
  React.useEffect(() => {
    if (!previousLikedRef.current && isLiked && likeIntentRef.current) {
      settledAnimationsRef.current = 0;
      setBurstId((current) => current + 1);
      setBurstActive(true);
    }

    if (previousLikedRef.current !== isLiked) {
      likeIntentRef.current = false;
    }

    previousLikedRef.current = isLiked;
  }, [isLiked]);

  const handleClick = React.useCallback(
    (event: LikeBurstClickEvent) => {
      onClick?.(event);

      if (event.defaultPrevented || disabled) {
        return;
      }

      const nextLiked = !isLiked;

      if (!controlled) {
        setInternalLiked(nextLiked);
      }

      likeIntentRef.current = nextLiked;

      onLikedChange?.(nextLiked);
    },
    [controlled, disabled, isLiked, onClick, onLikedChange],
  );

  // The burst leaves the DOM once the ring and every particle group have
  // finished, so long-lived liked items don't keep its layers mounted.
  const handleBurstAnimationEnd = React.useCallback(
    (event: React.AnimationEvent<HTMLSpanElement>) => {
      if (!LIKE_BURST_SETTLE_ANIMATIONS.has(event.animationName)) return;

      settledAnimationsRef.current += 1;

      if (settledAnimationsRef.current >= LIKE_BURST_SETTLE_COUNT) {
        setBurstActive(false);
      }
    },
    [],
  );

  const bursting = isLiked && burstActive;

  return (
    <ButtonPrimitive
      ref={ref}
      type="button"
      disabled={disabled}
      // With visible content, the accessible name must stay the visible text
      // (WCAG 2.5.3); aria-pressed alone conveys the state. The action label
      // only becomes the name when the control is icon-only.
      aria-label={children ? undefined : isLiked ? unlikeLabel : likeLabel}
      aria-pressed={isLiked}
      data-slot="like-burst"
      data-liked={isLiked}
      data-bursting={bursting ? "" : undefined}
      data-icon-only={children ? undefined : ""}
      className={cn(
        "like-burst relative inline-flex shrink-0 items-center justify-center gap-1.5 outline-none select-none focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50",
        children ? "w-fit" : "rounded-full text-muted-foreground",
        className,
      )}
      style={likeBurstStyle}
      onClick={handleClick}
      {...props}
    >
      <span
        data-slot="like-burst-icon"
        data-icon={children ? "inline-start" : undefined}
        className={cn("like-burst-icon", iconClassName)}
        aria-hidden="true"
      >
        {bursting ? (
          <span
            key={burstId}
            data-slot="like-burst-effects"
            className="like-burst-effects"
            onAnimationEnd={handleBurstAnimationEnd}
          >
            <span className="like-burst-ring" />
            <span className="like-burst-particles">
              {Array.from({ length: LIKE_BURST_PARTICLE_COUNT }, (_, index) => (
                <span className="like-burst-particle" key={index} />
              ))}
            </span>
          </span>
        ) : null}

        <HeartIcon className="like-burst-heart like-burst-heart-outline size-full" />
        <HeartIcon
          className="like-burst-heart like-burst-heart-fill size-full"
          fill="currentColor"
        />
      </span>

      {children ? (
        <span data-slot="like-burst-content">{children}</span>
      ) : null}
    </ButtonPrimitive>
  );
}

/* Defaults are layered for customization. Normal unlayered styles and
   utilities in a later layer can override them. */
@layer components {
  .like-burst {
    /* Its own heart colour, a touch pinker than Like's --ericts-like, to suit
       the bubble's violet. A dedicated token rather than --destructive: a
       like is not an error. */
    --like-burst-color: var(--ericts-like-burst);
    /* The bubble turns this colour before it hollows into a ring. Without
       the token the burst keeps a single hue rather than losing its shadows. */
    --like-burst-ring-color: var(
      --ericts-like-burst-ring,
      var(--like-burst-color)
    );
    --like-burst-size: 32px;
    --like-burst-duration: 700ms;
    --like-burst-ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  }

  .like-burst[data-icon-only] {
    width: max(2rem, calc(var(--like-burst-size) * 1.75));
    height: max(2rem, calc(var(--like-burst-size) * 1.75));
    transition: background-color 150ms var(--like-burst-ease-out);
  }

  /* Every burst length below is in em, and 1em is the heart, so the whole
     effect scales with --like-burst-size. */
  .like-burst-icon {
    position: relative;
    display: inline-flex;
    width: var(--like-burst-size);
    height: var(--like-burst-size);
    flex: none;
    font-size: var(--like-burst-size);
    transform: scale(1);
    transition: transform 160ms var(--like-burst-ease-out);
  }

  .like-burst:active .like-burst-icon {
    transform: scale(0.97);
  }

  .like-burst-heart {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    stroke-width: 1.75;
  }

  .like-burst-heart-outline {
    color: currentColor;
    transition:
      opacity 150ms var(--like-burst-ease-out),
      color 150ms var(--like-burst-ease-out);
  }

  .like-burst-heart-fill {
    color: var(--like-burst-color);
    opacity: 0;
    transition: opacity 150ms var(--like-burst-ease-out);
  }

  .like-burst[data-liked="true"] .like-burst-heart-outline {
    opacity: 0;
  }

  .like-burst[data-liked="true"] .like-burst-heart-fill {
    opacity: 1;
  }

  /* The outline collapses into the point the bubble grows from. */
  .like-burst[data-bursting] .like-burst-heart-outline {
    animation: like-burst-collapse var(--like-burst-duration) both;
  }

  .like-burst[data-bursting] .like-burst-heart-fill {
    animation: like-burst-pop var(--like-burst-duration) both;
  }

  .like-burst-effects {
    position: absolute;
    inset: 0;
    pointer-events: none;
  }

  /* A filled disc drawn as an inset shadow, so hollowing it into a ring is a
     paint-only spread change rather than a border-width layout change. */
  .like-burst-ring {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 1.3em;
    height: 1.3em;
    margin: -0.65em;
    border-radius: 50%;
    transform: scale(0);
    animation: like-burst-ring var(--like-burst-duration) both;
  }

  .like-burst-particles {
    position: absolute;
    inset: 0;
  }

  /* A zero-size anchor at the centre, turned to face its own direction, so
     travelling outward is a plain translateX in that rotated frame. */
  .like-burst-particle {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 0;
    height: 0;
    rotate: var(--like-burst-particle-angle, 0deg);
    animation: like-burst-particle var(--like-burst-duration) both;
  }

  /* Only 7 groups are choreographed below (LIKE_BURST_PARTICLE_COUNT in
     like-burst.tsx); anything past them has no direction, so hide it. */
  .like-burst-particle:nth-child(n + 8) {
    display: none;
  }

  /* Each group is a pair of dots set diagonally across its travel line, one
     larger than the other. */
  .like-burst-particle::before,
  .like-burst-particle::after {
    position: absolute;
    width: var(--like-burst-dot-size);
    height: var(--like-burst-dot-size);
    margin: calc(var(--like-burst-dot-size) / -2);
    border-radius: 50%;
    /* Mixing the heart and ring colours the long way round the hue wheel
       spreads the two into a rainbow, which white then softens to pastel. */
    background-color: color-mix(
      in oklch,
      color-mix(
          in oklch longer hue,
          var(--like-burst-color),
          var(--like-burst-ring-color) var(--like-burst-dot-hue)
        )
        70%,
      white
    );
    transform: scale(0);
    animation: like-burst-dot var(--like-burst-duration) both;
    content: "";
  }

  .like-burst-particle::before {
    --like-burst-dot-size: 0.15em;
    --like-burst-dot-hue: var(--like-burst-particle-hue-a);
    top: 0.13em;
    left: 0.075em;
  }

  .like-burst-particle::after {
    --like-burst-dot-size: 0.11em;
    --like-burst-dot-hue: var(--like-burst-particle-hue-b);
    top: -0.13em;
    left: -0.075em;
  }

  /* Seven groups, clockwise from the top. Each takes two neighbouring stops
     of the heart→ring sweep, so adjacent groups share a colour and the burst
     reads as one continuous wheel. */
  .like-burst-particle:nth-child(1) {
    --like-burst-particle-angle: -90deg;
    --like-burst-particle-hue-a: 0%;
    --like-burst-particle-hue-b: 14.29%;
  }

  .like-burst-particle:nth-child(2) {
    --like-burst-particle-angle: -38.57deg;
    --like-burst-particle-hue-a: 14.29%;
    --like-burst-particle-hue-b: 28.57%;
  }

  .like-burst-particle:nth-child(3) {
    --like-burst-particle-angle: 12.86deg;
    --like-burst-particle-hue-a: 28.57%;
    --like-burst-particle-hue-b: 42.86%;
  }

  .like-burst-particle:nth-child(4) {
    --like-burst-particle-angle: 64.29deg;
    --like-burst-particle-hue-a: 42.86%;
    --like-burst-particle-hue-b: 57.14%;
  }

  .like-burst-particle:nth-child(5) {
    --like-burst-particle-angle: 115.71deg;
    --like-burst-particle-hue-a: 57.14%;
    --like-burst-particle-hue-b: 71.43%;
  }

  .like-burst-particle:nth-child(6) {
    --like-burst-particle-angle: 167.14deg;
    --like-burst-particle-hue-a: 71.43%;
    --like-burst-particle-hue-b: 85.71%;
  }

  .like-burst-particle:nth-child(7) {
    --like-burst-particle-angle: 218.57deg;
    --like-burst-particle-hue-a: 85.71%;
    --like-burst-particle-hue-b: 100%;
  }

  /* One clock for every layer: the percentages below are the choreography,
     and --like-burst-duration stretches all of it together. The heart is
     the payoff, so it lands early and the dots carry the tail.

     0–8%     outline collapses to a point
     3–22%    bubble grows from that point, turning ring-coloured from 15%
     20–38%   filled heart bursts out of the bubble, past full size
     22–40%   bubble hollows around it until the ring is gone
     38–54%   heart settles back to full size
     22–100%  dot pairs fly out, swell, then shrink away */
  @keyframes like-burst-collapse {
    0% {
      opacity: 1;
      transform: scale(1);
      animation-timing-function: cubic-bezier(0.55, 0, 1, 0.45);
    }

    8%,
    100% {
      opacity: 0;
      transform: scale(0);
    }
  }

  /* Each offset appears once. A keyframe that omits a property leaves that
     property's interval, and its easing, to the keyframes that name it. The
     0.66em spread overfills the 0.65em radius, so the disc has no pinhole. */
  @keyframes like-burst-ring {
    0%,
    3% {
      transform: scale(0);
      box-shadow: inset 0 0 0 0.66em var(--like-burst-color);
      animation-timing-function: var(--like-burst-ease-out);
    }

    /* The colour turns late and fast: an even blend lingers on a washed-out
       pink-lavender midpoint. */
    15% {
      box-shadow: inset 0 0 0 0.66em var(--like-burst-color);
      animation-timing-function: ease-in-out;
    }

    22% {
      transform: scale(1);
      box-shadow: inset 0 0 0 0.66em var(--like-burst-ring-color);
      animation-timing-function: var(--like-burst-ease-out);
    }

    40%,
    100% {
      transform: scale(1);
      box-shadow: inset 0 0 0 0 var(--like-burst-ring-color);
    }
  }

  /* Two segments rather than one overshooting curve: an ease-out spends most
     of its travel in the first few frames, so the heart is near full size
     almost as soon as it appears, and the settle is its own gentle move. */
  @keyframes like-burst-pop {
    0%,
    20% {
      transform: scale(0);
      animation-timing-function: var(--like-burst-ease-out);
    }

    38% {
      transform: scale(1.15);
      animation-timing-function: ease-in-out;
    }

    54%,
    100% {
      transform: scale(1);
    }
  }

  @keyframes like-burst-particle {
    0%,
    22% {
      transform: translateX(0.6em);
      animation-timing-function: cubic-bezier(0.21, 0.61, 0.35, 1);
    }

    100% {
      transform: translateX(1em);
    }
  }

  @keyframes like-burst-dot {
    0%,
    22% {
      transform: scale(0);
      animation-timing-function: var(--like-burst-ease-out);
    }

    32% {
      transform: scale(1);
      animation-timing-function: cubic-bezier(0.55, 0.085, 0.68, 0.53);
    }

    100% {
      transform: scale(0);
    }
  }

  /* Icon-only hover tints the heart and fills the round hit area with a halo
     of the same colour. The heart is targeted directly because the root's
     text colour is a utility, which outranks this layer. */
  @media (hover: hover) and (pointer: fine) {
    .like-burst[data-icon-only]:hover {
      background-color: color-mix(
        in oklch,
        var(--like-burst-color) 12%,
        transparent
      );
    }

    .like-burst[data-icon-only]:hover .like-burst-heart-outline {
      color: var(--like-burst-color);
    }
  }
}

/* Motion guards override ordinary customization, including inline timing.
   Keep these outside the defaults layer; only motion declarations are important. */
@media (prefers-reduced-motion: reduce) {
  .like-burst-icon,
  .like-burst:active .like-burst-icon {
    transform: none !important;
  }

  /* The hearts keep their opacity crossfade; the burst ends where it starts.
     Zero duration instead of `none` so animationend still fires and the
     component can unmount the burst. `both` fill ends every layer invisible. */
  .like-burst[data-bursting] .like-burst-heart-outline,
  .like-burst[data-bursting] .like-burst-heart-fill,
  .like-burst-ring,
  .like-burst-particle,
  .like-burst-particle::before,
  .like-burst-particle::after {
    animation-duration: 0ms !important;
    animation-delay: 0ms !important;
  }
}
